// Baut die Buchung. eventTypeId stammt ausschliesslich aus der Kunden-Config:
// selbst wenn ein Agent eine fremde ID mitschickt, wird sie ignoriert.
const e = $input.first().json;
const p = e.params || {};
const c = e.config || {};

function text(w, max) { return String(w == null ? '' : w).trim().slice(0, max); }

const name = text(p.name, 120);
const start = String(p.start || p.zeitpunkt || '').trim();
const telefon = text(p.telefon || e.from_number, 32);
// Cal.com verlangt eine E-Mail. Am Telefon nennt kaum jemand eine - deshalb
// eine technische Adresse, entweder aus der Config oder als Sammeladresse.
const email = text(p.email, 160) || String(c.buchung_platzhalter_email || '')
  || ('telefontermin+' + String(e.kunde_id || 'unbekannt').replace(/[^a-z0-9]/gi, '') + '@ak-assistance.de');

let fehler = '';
if (!c.cal_event_type_id) fehler = 'kalender nicht konfiguriert';
  else if (String(c.kalender_typ || 'calcom') !== 'calcom') fehler = 'kalender nicht unterstuetzt';
else if (!name) fehler = 'name fehlt';
else if (!/^\d{4}-\d{2}-\d{2}T/.test(start)) fehler = 'startzeit fehlt oder ungueltig';

const anhang = { name: name, email: email, timeZone: c.zeitzone, language: 'de' };
if (telefon) anhang.phoneNumber = telefon;

return [{ json: Object.assign({}, e, {
  buchung: {
    eventTypeId: Number(c.cal_event_type_id),
    start: start,
    attendee: anhang,
    metadata: {
      // Herkunft mitschreiben, damit im Kalender sichtbar ist, wer gebucht hat.
      quelle: 'ak-telefonagent',
      kunde_id: String(e.kunde_id),
      agent_typ: String(e.agent_typ),
    },
    bookingFieldsResponses: { notizen: text(p.anliegen, 500) },
  },
  fehler: fehler,
}) }];

const ktx = $('Eingaben pruefen').first().json;
// Vereinheitlicht die Antwort. Kein Sub-Workflow gibt je etwas anderes
// zurueck als { success, data, message } - darauf bauen die Retell-Agenten
// ihre Erfolgs- und Fehlerzweige auf.
function antwort(success, data, message) {
  return { success: !!success, data: data || {}, message: String(message || '') };
}

if (ktx.fehler) return [{ json: antwort(false, {}, ktx.fehler) }];

const r = $input.first().json || {};
if (r.error) return [{ json: antwort(false, { buchung_erfolgreich: false }, 'kalender nicht erreichbar') }];

const code = Number(r.statusCode);
const b = r.body || {};
if (code >= 400) {
  // 409 = Slot inzwischen vergeben. Das ist der haeufigste Fall und der Agent
  // soll dann neue Zeiten anbieten, statt einen Fehler vorzulesen.
  const msg = code === 409 ? 'termin nicht mehr frei' : 'buchung fehlgeschlagen';
  return [{ json: antwort(false, { buchung_erfolgreich: false, code: code }, msg) }];
}

const d = b.data || {};
return [{ json: antwort(true, {
  buchung_erfolgreich: true,
  bestaetigungsnummer: String(d.uid || d.id || ''),
  start: String(d.start || ktx.buchung.start),
  ende: String(d.end || ''),
}, 'termin gebucht') }];
